import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Conclusioni","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/p_matematica-per-informatica/pc/pcje.md","filePath":"lezioni/p_matematica-per-informatica/pc/pcje.md"}`),a={name:`lezioni/p_matematica-per-informatica/pc/pcje.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="conclusioni" tabindex="-1">Conclusioni <a class="header-anchor" href="#conclusioni" aria-label="Permalink to “Conclusioni”">​</a></h1><p>Anche se l&#39;argomento richiederebbe ben altri approfondimenti, terminiamo qui il discorso teorico sull&#39;algebra binaria di Boole, lasciando agli informatici uno studio più rigoroso ed ampio.</p><p>Quindi ora abbiamo un&#39;algebra con cui trattare i &quot;pacchetti di dati&quot;, abbiamo determinato gli enti su cui lavorare (cioè i &quot;pacchetti&quot; di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>0</mn></mrow><annotation encoding="application/x-tex">0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> ed <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>); ora dobbiamo collegare le operazioni viste in algebra (passaggio al complementare, somma, prodotto) a tali enti e trasformare tutto in circuiti elettrici.</p><p>Nel prossimo capitolo metteremo in pratica quanto visto in modo teorico applicando l&#39;algebra a dei fili percorsi o meno da corrente (i due stati, la variabile ed il suo complementare) e collegando tali fatti alle tavole di verità ed alle operazioni viste in logica per i predicati (and logico, or logico), fino alla costruzione di un semplice circuito che faccia l&#39;operazione di somma fra due bit: la moltiplicazione poi di tale circuito ci permetterà di poter far eseguire le operazioni in modo automatico da una macchina; infine, sostituendo ai numeri dei concetti logici, potremo avere la base di una macchina per elaborare tali concetti (elaboratore elettronico).</p>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};